export type MediaType = 'video' | 'audio' | 'image';

export interface MediaItem {
  /** Normalized media kind. */
  type: MediaType;
  /** Direct link, unless `pending` is true. */
  url: string;
  /**
   * True when `url` streams encoding progress instead of bytes.
   * Call `resolveUrl()` on it, or pass `resolve: true` to `download()`.
   */
  pending: boolean;
  /** Quality label as reported by the API, e.g. "360p" or "hd_no_watermark". */
  quality?: string | null;
  mimeType?: string | null;
  filesize?: number | null;
  extension?: string | null;
}

export interface DownloadResult {
  /** True when at least one media link was found. */
  ok: boolean;
  /** Platform label, e.g. "tiktok". */
  platform: string;
  /** The URL you passed in. */
  sourceUrl: string;
  /** Endpoint that produced this result. */
  endpoint: string;
  title: string | null;
  author: string | null;
  thumbnail: string | null;
  /** Duration in seconds, normalized from whatever unit the API used. */
  duration: number | null;
  /** The untouched duration value, in case you want to interpret it yourself. */
  durationRaw: unknown;
  /** Every link found, best quality first. */
  media: MediaItem[];
  /** Chosen video link for the requested quality. */
  video: string | null;
  /** Chosen audio link for the requested quality. */
  audio: string | null;
  /** Quality label of the chosen video. */
  videoQuality: string | null;
  /** True when any link still needs resolving. */
  pending: boolean;
  /** Image links, for slideshow-style posts. */
  images: string[];
  /** Raw payload, for fields this package does not map. */
  raw: Record<string, unknown>;
}

export interface ProgressEvent {
  /** 0-100. */
  percent: number;
  /** Server-reported state, e.g. "in_progress" or "finalizing". */
  status: string;
}

export interface DownloadOptions {
  /** "best" | "worst" | "360p" | "720p" | "1080p" | ... */
  quality?: string;
  /** Use a different endpoint for this call. */
  endpoint?: string;
  /** Resolve progress-stream links before returning. Can take ~25s. */
  resolve?: boolean;
  /** Called while a progress stream is being resolved. */
  onProgress?: (event: ProgressEvent) => void;
  /** youtubedl only: "mp3" | "video". */
  format?: string;
  /** bilibili-download only: cookie for gated videos. */
  cookies?: string;
  /** downallv4 only: set false to skip the audio lookup. */
  audio?: boolean;
}

export interface SaveOptions extends DownloadOptions {
  /** Save video or audio. Defaults to "video". */
  type?: 'video' | 'audio';
}

export interface SaveResult {
  path: string;
  bytes: number;
  sourceUrl: string;
  mediaUrl: string;
}

export interface ClientOptions {
  /** Defaults to https://api.satoru.click */
  baseUrl?: string;
  /** Per-request timeout in ms. Default 60000. */
  timeout?: number;
  /** Retries for transient failures. Default 2. */
  retries?: number;
  /** Endpoint every call uses. Default "downallv2". */
  endpoint?: string;
  headers?: Record<string, string>;
  userAgent?: string;
}

export interface RateLimitInfo {
  limit: number;
  remaining: number;
  reset: string | null;
}

export interface ResolvedUrl {
  /** Direct file link. */
  url: string;
  /** Duration in seconds, when the server reported it. */
  duration: number | null;
  /** Server-suggested filename, when available. */
  filename: string | null;
}

export type ErrorCode =
  | 'INVALID_URL'
  | 'UNKNOWN_ENDPOINT'
  | 'NETWORK'
  | 'TIMEOUT'
  | 'BAD_JSON'
  | 'RATE_LIMITED'
  | 'UPSTREAM'
  | 'NO_MEDIA'
  | 'RESOLVE_FAILED'
  | 'ERROR';

export class MediaDownloaderError extends Error {
  name: 'MediaDownloaderError';
  code: ErrorCode;
  status?: number;
  endpoint?: string;
}

export class MediaDownloader {
  constructor(options?: ClientOptions);

  baseUrl: string;
  timeout: number;
  retries: number;
  endpoint: string;
  /** Rate-limit info from the most recent request. */
  lastRateLimit: RateLimitInfo | null;

  /** Fetch media info for any http(s) URL. */
  download(url: string, options?: DownloadOptions): Promise<DownloadResult>;
  /** Call a specific endpoint. */
  fromEndpoint(endpoint: string, url: string, params?: DownloadOptions): Promise<DownloadResult>;
  /** Ready-to-use video link, resolving a progress stream if needed. */
  videoUrl(url: string, options?: DownloadOptions): Promise<string | null>;
  /** Ready-to-use audio link, resolving a progress stream if needed. */
  audioUrl(url: string, options?: DownloadOptions): Promise<string | null>;
  /** Download to disk. */
  save(url: string, destination: string, options?: SaveOptions): Promise<SaveResult>;

  static readonly endpoints: string[];
  static readonly primaryEndpoint: string;
  static detect(url: string): string;
}

export function download(url: string, options?: DownloadOptions): Promise<DownloadResult>;
export function fromEndpoint(endpoint: string, url: string, params?: DownloadOptions): Promise<DownloadResult>;
export function save(url: string, destination: string, options?: SaveOptions): Promise<SaveResult>;
export function detectPlatform(url: string): string;

/** Drain a progress stream and return the real file link. Plain URLs pass through. */
export function resolveUrl(
  url: string,
  options?: { timeoutMs?: number; onProgress?: (event: ProgressEvent) => void; userAgent?: string }
): Promise<ResolvedUrl>;

/** True when a URL streams progress events rather than the file. */
export function needsResolve(url: string): boolean;

/** Pick one media entry by type and quality preference. */
export function pickMedia(media: MediaItem[], type: MediaType, quality?: string): MediaItem | null;

/** Numeric rank for a quality label, for sorting. */
export function qualityScore(label: string): number;

export const ERROR_CODES: Record<string, ErrorCode>;
export const endpoints: string[];
export const PRIMARY_ENDPOINT: string;
export const API_BASE_URL: string;
